layers.vertex:
attribute vec3 aO; attribute float aT; uniform float uTime; varying vec2 vP; varying float vU;
    void main(){
      float u = uTime - aT - 0.18; if (u < 0. || u > 0.80){ gl_Position = vec4(2.,2.,2.,1.); return; }
      float S = 5.50; vP = position.xy*S; vU = u;
      gl_Position = projectionMatrix*viewMatrix*vec4(aO + vec3(position.x*S, .03, -position.y*S), 1.);
    }

layers.fragment:
uniform vec3 uGold, uOrange; varying vec2 vP; varying float vU; float lcore(float d, float w){ return exp(-(d*d)/(w*w)); }
    void main(){
      float r = length(vP), R = 5.00, E = 0.35;
      float k = clamp(vU/E, 0., 1.), rr = R*k;                               // linear expansion
      float held = step(E, vU), pk = vU >= E && vU < E + .033 ? 1.7 : 1.;    // 2-frame peak when it reaches the limit
      float fade = 1. - smoothstep(E + .12, E + .45, vU);
      float w = mix(.03, .018, k);
      float ring = exp(-pow(abs(r - rr)/w, 2.4)), hot = lcore(r - rr, w*.3);
      float wake = smoothstep(rr - .7, rr, r)*step(r, rr)*(1. - held)*.03;  // faint thin wake just behind the moving front (ornament, dimmer than the limit)
      float lim = (.55 + .45*held)*pk*fade;
      float core = exp(-r*r*3.)*(vU < .033 ? 1.1 : .5*exp(-vU*9.));            // opening glow at the Fighter
      float edge = smoothstep(5.50, 5.20, r);
      vec3 outc = (uOrange*(ring*lim + wake*fade + core*.6) + mix(uGold, vec3(1.), .4)*hot*lim*.6)*edge;
      if (max(outc.r, max(outc.g, outc.b)) < .002) discard;
      gl_FragColor = vec4(outc, 1.);
    }
